import * as THREE from './vendor/three.module.js';
import {PainterRenderer} from './painter-renderer.js';
import {createWorld} from './world.js';
import {CameraControls,orbitOffset} from './camera-controls.js';
import {Fighter,MOVES,inStrikeRange} from './combat.js';
import {Effects} from './effects.js';
const $=id=>document.getElementById(id);
let renderer,software=false;
try{renderer=new THREE.WebGLRenderer({canvas:$('world'),antialias:true,powerPreference:'high-performance'});}catch{software=true;renderer=new PainterRenderer();$('world').replaceWith(renderer.domElement);renderer.domElement.id='world';}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.shadowMap.enabled=!software;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const scene=new THREE.Scene();scene.background=new THREE.Color('#bed0bd');scene.fog=new THREE.Fog('#bed0bd',45,170);
const camera=new THREE.PerspectiveCamera(53,innerWidth/innerHeight,.15,260);
scene.add(new THREE.HemisphereLight('#fff0ce','#718668',2));
const sun=new THREE.DirectionalLight('#ffe5b1',2.3);sun.position.set(-35,60,28);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-45,right:45,top:45,bottom:-45,far:150});sun.shadow.bias=-.0015;scene.add(sun);scene.add(sun.target);
const world=createWorld(scene,software),{player,wen,bosses,dummy,herbs,obstacles,cameraWalls}=world;
const fighter=new Fighter(),effects=new Effects(scene),keys=new Set(),defeated=new Set();
let playing=false,paused=false,hp=100,copper=0,remedies=3,talked=false,toastTimer=0,healCooldown=0,activeBoss=null;
let dodgeDirection=new THREE.Vector3(),movement=new THREE.Vector3(),time=0,dummyHeal=0,lastAction='',hudTime=0;
try{const s=JSON.parse(localStorage.getItem('dust-rice-v1'));if(s){copper=s.copper??0;remedies=s.remedies??3;talked=!!s.talked;for(const n of s.defeated??[])defeated.add(n);}}catch{}
for(const b of bosses)if(defeated.has(b.name)){b.hp=0;b.g.visible=b.shadow.visible=b.ring.visible=false;}
function save(){try{localStorage.setItem('dust-rice-v1',JSON.stringify({copper,remedies,talked,defeated:[...defeated]}));}catch{}}
function toast(text){$('toast').textContent=text;$('toast').style.opacity=1;toastTimer=2.5;}
const controls=new CameraControls(renderer.domElement,{button:$('cameraMode'),status:$('cameraStatus'),isActive:()=>playing&&!paused,onUnlock:()=>{if(!paused)pause(true);},onMessage:toast});
if(software){controls.mode='free';controls.sync();}
function pause(value){paused=value;keys.clear();$('menu').hidden=!value;if(value){controls.release();}else controls.capture();}
$('start').onclick=()=>{playing=true;pause(false);$('start').textContent='Return to the valley →';};
$('pause').onclick=()=>{if(playing)pause(!paused);};
$('reset').onclick=()=>{if(confirm('Erase saved progress and begin again?')){localStorage.removeItem('dust-rice-v1');location.reload();}};
function dialog(title,text){paused=true;keys.clear();controls.release();$('speaker').textContent='VILLAGE ELDER WEN';$('dialogTitle').textContent=title;$('dialogText').textContent=text;$('dialog').hidden=false;}
$('closeDialog').onclick=()=>{$('dialog').hidden=true;paused=false;};
function interact(){if(player.g.position.distanceTo(wen.g.position)<4){talked=true;hp=100;fighter.stamina=100;if(defeated.size===3)dialog('Tonight, we eat together.','The tribute is broken and the mountain road is open. The valley is ours again. You have completed the first chapter.');else if(copper>=10){copper-=10;remedies+=2;dialog('Rest your sword arm.','Two fresh remedies for ten copper. I have patched your coat. Watch for the red circle before a heavy blow: dodge, guard, or meet it with a well-timed parry.');}else{remedies=Math.max(3,remedies);dialog('A blade is only the beginning.','Try your three-cut chain on the training post. J strikes, K breaks a guard, and R sweeps every enemy around you. Hold F to guard; raise it just before a blow for a parry. The collector camps southwest. The marsh guardian waits east, and the warden holds the northern road.');}save();}else{const herb=herbs.find(g=>g.visible&&g.position.distanceTo(player.g.position)<3);if(herb){herb.visible=false;remedies++;effects.burst(herb.position.clone().add(new THREE.Vector3(0,.7,0)),'dust',8);save();toast('+1 remedy');}}}
function startMove(kind){if(!playing||paused)return;if(!fighter.start(kind))return;if(kind==='dodge'){dodgeDirection.copy(movement);if(dodgeDirection.lengthSq()<.1)dodgeDirection.set(Math.sin(player.g.rotation.y),0,Math.cos(player.g.rotation.y));effects.burst(player.g.position.clone().add(new THREE.Vector3(0,.15,0)),'dust',6);}else{const move=MOVES[fighter.action];const target=[dummy,...bosses].filter(b=>b.hp>0&&b.g.position.distanceTo(player.g.position)<move.range+1).sort((a,b)=>a.g.position.distanceTo(player.g.position)-b.g.position.distanceTo(player.g.position))[0];if(target&&kind!=='sweep')player.g.rotation.y=Math.atan2(target.g.position.x-player.g.position.x,target.g.position.z-player.g.position.z);}}
addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Escape'){if(playing&&!paused)pause(true);return;}if(e.code==='KeyC'){controls.toggle();return;}if(!playing||paused)return;if(e.code==='KeyJ')startMove('light');if(e.code==='KeyK')startMove('heavy');if(e.code==='KeyR')startMove('sweep');if(e.code==='Space')startMove('dodge');if(e.code==='KeyE')interact();if(e.code==='KeyQ'&&remedies>0&&hp<100&&healCooldown<=0){remedies--;hp=Math.min(100,hp+45);healCooldown=1.5;effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1,0)),'parry',12);toast('+45 health');save();}});
addEventListener('keyup',e=>keys.delete(e.code));
addEventListener('blur',()=>{keys.clear();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing&&!paused)pause(true);});
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button===0&&(controls.mode==='free'||document.pointerLockElement===renderer.domElement))startMove('light');});
function moveActor(actor,dir,distance){const p=actor.g.position,old=p.clone();p.addScaledVector(dir,distance);p.x=THREE.MathUtils.clamp(p.x,-109,109);p.z=THREE.MathUtils.clamp(p.z,-109,109);if(obstacles.some(o=>Math.hypot(p.x-o.x,p.z-o.z)<o.r))p.copy(old);}
function dealHit(move){let hits=0;for(const b of [dummy,...bosses]){if(b.hp<=0||!inStrikeRange(player.g.position.x,player.g.position.z,player.g.rotation.y,b.g.position.x,b.g.position.z,move))continue;b.hp=Math.max(0,b.hp-move.damage);effects.hit(b,move.damage);hits++;if(b.dummy){dummyHeal=2;dummy.g.rotation.z=(hits%2?1:-1)*.08;}else{const push=b.g.position.clone().sub(player.g.position);push.y=0;push.normalize();moveActor(b,push,move.push);if(move.stagger&&b.state!=='windup'){b.state='stagger';b.timer=move.stagger;}else if(move.key==='heavy'){b.state='stagger';b.timer=move.stagger;}if(b.hp<=0){defeated.add(b.name);b.g.visible=b.shadow.visible=b.ring.visible=false;copper+=b.reward;effects.burst(b.g.position.clone().add(new THREE.Vector3(0,2,0)),'hit',24);toast(b.name+' defeated · +'+b.reward+' copper');save();}}}if(hits)$('moveName').textContent=move.name;}
function incoming(b){const result=fighter.receive(24);if(result.kind==='evade'){effects.number(player.g.position.clone().add(new THREE.Vector3(0,1.5,0)),'EVADE');return;}if(result.kind==='parry'){b.state='stagger';b.timer=1.35;effects.hit(b,0,'parry');effects.number(player.g.position.clone().add(new THREE.Vector3(0,2,0)),'PARRY');b.hp=Math.max(1,b.hp-12);return;}if(result.kind==='block'){effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1.6,0)),'parry',10);effects.number(player.g.position.clone().add(new THREE.Vector3(0,1.6,0)),'GUARD');return;}hp=Math.max(0,hp-result.damage);effects.hit(player,result.damage);if(result.kind==='break')toast('Guard broken');}
function updateBoss(b,dt){if(b.hp<=0)return;const dist=b.g.position.distanceTo(player.g.position);if(dist>24){b.state='idle';b.timer=0;b.g.position.lerp(b.home,Math.min(1,dt*.5));b.legs.forEach(l=>l.rotation.x=0);b.arms[1].rotation.set(0,0,0);}else{activeBoss=b;b.g.rotation.y=Math.atan2(player.g.position.x-b.g.position.x,player.g.position.z-b.g.position.z);b.timer-=dt;if(b.state==='idle')b.state='chase';if(b.state==='chase'){const direction=player.g.position.clone().sub(b.g.position);direction.y=0;direction.normalize();if(dist>3.8)moveActor(b,direction,dt*(b.hp<b.max*.5?3.6:2.8));b.legs.forEach((l,i)=>l.rotation.x=Math.sin(time*8+i*Math.PI)*.4);b.arms[1].rotation.x=0;if(dist<5){b.state='windup';b.timer=b.hp<b.max*.5?.72:.98;}}else if(b.state==='windup'){b.arms[1].rotation.x=-2.6;b.torso.rotation.z=-.09;if(b.timer<=0){b.state='recover';b.timer=1.15;b.arms[1].rotation.x=-1;if(dist<5.8)incoming(b);}}else if(b.state==='recover'){b.arms[1].rotation.x=THREE.MathUtils.damp(b.arms[1].rotation.x,0,6,dt);if(b.timer<=0)b.state='chase';}else if(b.state==='stagger'){b.torso.rotation.z=Math.sin(time*16)*.06;b.arms[1].rotation.x=-.3;if(b.timer<=0)b.state='chase';}}
 b.ring.position.copy(b.g.position);b.ring.position.y=.025;b.ring.material.color.set(b.state==='windup'?'#db5c3f':b.state==='stagger'?'#b8d2cb':'#c6aa69');b.ring.material.opacity=b.state==='windup'?.55+Math.sin(time*18)*.15:.25;if(b.state!=='windup'&&b.state!=='stagger')b.torso.rotation.z=0;}
function posePlayer(dt){const moving=movement.lengthSq()>.01;const running=keys.has('ShiftLeft')&&fighter.stamina>5;const swing=Math.sin(time*(running?13:9))*(moving?.55:0);player.legs[0].rotation.x=swing;player.legs[1].rotation.x=-swing;player.arms[0].rotation.set(-swing*.5,0,.03);player.arms[1].rotation.set(swing*.4,0,-.03);player.torso.rotation.set(0,0,0);player.g.position.y=moving?Math.abs(Math.sin(time*9))*.035:0;player.blade.rotation.set(0,0,0);
 if(fighter.action){const m=MOVES[fighter.action],p=Math.min(1,fighter.time/(m.windup+m.active)),s=Math.sin(Math.min(1,p)*Math.PI);if(fighter.action==='heavy'||fighter.action==='light3'){player.arms[1].rotation.x=-2.8*(1-p)-.7;player.torso.rotation.x=.16*s;}else{const side=fighter.action==='light2'?-1:1;player.arms[1].rotation.x=-1.35;player.arms[1].rotation.z=side*(1.5-p*3);player.torso.rotation.y=side*(.6-p*1.1);}if(fighter.action==='sweep'){player.torso.rotation.y=fighter.time*12;player.arms[0].rotation.x=-1;player.arms[1].rotation.z=-1.3;}}
 if(fighter.guarding){player.arms[0].rotation.set(-1.2,0,-.5);player.arms[1].rotation.set(-1.8,0,.5);player.torso.rotation.x=.08;}
 if(fighter.dodge>0){player.g.position.y=Math.sin((.4-fighter.dodge)/.4*Math.PI)*.25;player.torso.rotation.x=.45;player.arms[0].rotation.x=-.6;player.arms[1].rotation.x=-.9;}
}
function update(dt){time+=dt;healCooldown=Math.max(0,healCooldown-dt);fighter.tick(dt,keys.has('KeyF'));if(keys.has('ArrowLeft'))controls.yaw+=dt*1.8;if(keys.has('ArrowRight'))controls.yaw-=dt*1.8;if(keys.has('ArrowUp'))controls.pitch=Math.max(.12,controls.pitch-dt);if(keys.has('ArrowDown'))controls.pitch=Math.min(1.28,controls.pitch+dt);movement.set(Number(keys.has('KeyD'))-Number(keys.has('KeyA')),0,Number(keys.has('KeyS'))-Number(keys.has('KeyW'))).applyAxisAngle(new THREE.Vector3(0,1,0),controls.yaw).normalize();if(fighter.dodge>0)moveActor(player,dodgeDirection,dt*14);else{const moving=movement.lengthSq()>.01,running=keys.has('ShiftLeft')&&fighter.stamina>5&&!fighter.busy&&!fighter.guarding;const speed=fighter.action?1.5:fighter.guarding?2.5:running?8.5:5.5;if(moving){moveActor(player,movement,dt*speed);if(!fighter.action)player.g.rotation.y=Math.atan2(movement.x,movement.z);if(running)fighter.stamina=Math.max(0,fighter.stamina-dt*34);}}const hit=fighter.consumeHit();if(hit)dealHit(hit);if(fighter.action!==lastAction){if(fighter.action)$('moveName').textContent=MOVES[fighter.action].name;lastAction=fighter.action;}
 activeBoss=null;for(const b of bosses)updateBoss(b,dt);if(dummyHeal>0){dummyHeal-=dt;if(dummyHeal<=0)dummy.hp=dummy.max;}dummy.g.rotation.z=THREE.MathUtils.damp(dummy.g.rotation.z,0,9,dt);posePlayer(dt);for(const a of world.actors){a.shadow.position.set(a.g.position.x,.014,a.g.position.z);}
 if(hp<=0){hp=100;fighter.stamina=100;fighter.action=null;fighter.recovery=0;player.g.position.set(0,0,15);for(const b of bosses)if(b.hp>0){b.hp=b.max;b.g.position.copy(b.home);b.state='idle';}toast('Wen brought you home. Study the windup and try again.');}
}
function text(id,value){const e=$(id);if(e.textContent!==value)e.textContent=value;}
function hud(){ $('health').style.width=hp+'%';$('stamina').style.width=fighter.stamina+'%';text('coins',copper+' copper');text('potions',remedies+' remedies');text('progress',defeated.size+' / 3 threats defeated');text('questTitle',defeated.size===3?'The valley breathes again':'A village under tribute');text('questText',defeated.size===3?'Return to Wen by the well.':talked?'Collector southwest · Guardian east · Warden north.':'Speak to Wen by the well, or practice at the training post.');$('bossUI').hidden=!activeBoss;if(activeBoss){text('bossName',activeBoss.name);$('bossHealth').style.width=activeBoss.hp/activeBoss.max*100+'%';text('bossState',activeBoss.state==='windup'?'HEAVY STRIKE · DODGE / PARRY':activeBoss.state==='stagger'?'STAGGERED · STRIKE NOW':activeBoss.state==='recover'?'AN OPENING':'STAND YOUR GROUND');}
 let hint='';if(player.g.position.distanceTo(wen.g.position)<4)hint='E · Speak to Wen';else if(herbs.some(g=>g.visible&&g.position.distanceTo(player.g.position)<3))hint='E · Gather remedy';else if(player.g.position.distanceTo(dummy.g.position)<7)hint='Training post · '+dummy.hp+' / 300 · J chain / K heavy / R sweep';text('hint',hint);$('hint').style.display=hint?'block':'none';text('sweepTimer',fighter.sweepCooldown>0?fighter.sweepCooldown.toFixed(1)+'s':'Ready');$('skillSweep').classList.toggle('cooling',fighter.sweepCooldown>0);$('skillGuard').classList.toggle('active',fighter.guarding);$('skillLight').classList.toggle('active',!!fighter.action?.startsWith('light'));$('skillHeavy').classList.toggle('active',fighter.action==='heavy');text('combo',fighter.action?.startsWith('light')?'CUT '+fighter.action.at(-1)+' / 3':fighter.guarding?'GUARD':fighter.dodge>0?'DODGE':'');
 const p=player.g.position;const location=p.z<-40?'THE NORTHERN ROAD':p.x>26?'THE REED MARSH':p.x<-28?'THE COLLECTOR’S CAMP':'SHUǏTIÁN VILLAGE';if($('location').firstChild.textContent!==location+' ')$('location').firstChild.textContent=location+' ';const ctx=$('map').getContext('2d');ctx.clearRect(0,0,180,180);ctx.fillStyle='#354c3e';ctx.fillRect(0,0,180,180);ctx.strokeStyle='#c1b88b55';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(90,20);ctx.lineTo(90,155);ctx.moveTo(40,120);ctx.lineTo(140,120);ctx.stroke();for(const o of obstacles){ctx.fillStyle='#bdb08b';ctx.fillRect(90+o.x*.65-3,90+o.z*.65-3,6,6);}for(const b of bosses){ctx.fillStyle=b.hp>0?'#d18b61':'#8baf8c';ctx.beginPath();ctx.arc(90+b.home.x*.65,90+b.home.z*.65,4,0,7);ctx.fill();}ctx.save();ctx.translate(90+p.x*.65,90+p.z*.65);ctx.rotate(-player.g.rotation.y);ctx.fillStyle='#fff3cb';ctx.beginPath();ctx.moveTo(0,5);ctx.lineTo(-3,-3);ctx.lineTo(3,-3);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#e4d9b8';ctx.font='10px Arial';ctx.fillText('N',86,15);
}
const raycaster=new THREE.Raycaster(),cameraTarget=new THREE.Vector3(),desiredCamera=new THREE.Vector3(),forward=new THREE.Vector3();camera.position.set(32,20,36);let last=0,accumulator=0,frames=0,statsTime=0,lastStats=performance.now();
function frame(now){requestAnimationFrame(frame);const realDt=Math.min((now-last)/1000||.016,.1);last=now;const active=playing&&!paused;if(active){accumulator+=effects.hitStop>0?0:realDt;let steps=0;while(accumulator>=1/60&&steps++<6){update(1/60);accumulator-=1/60;}}else accumulator=0;
 cameraTarget.copy(player.g.position).add(new THREE.Vector3(0,1.4,0));const orbit=orbitOffset(controls.yaw,controls.pitch,controls.distance);desiredCamera.copy(cameraTarget).add(new THREE.Vector3(orbit.x,orbit.y,orbit.z));if(!playing){cameraTarget.set(0,1,-2);desiredCamera.set(32,20,36);}camera.position.lerp(desiredCamera,1-Math.exp(-realDt*10));if(playing){forward.copy(camera.position).sub(cameraTarget);raycaster.set(cameraTarget,forward.normalize());raycaster.far=camera.position.distanceTo(cameraTarget);const hit=raycaster.intersectObjects(cameraWalls,false)[0];if(hit)camera.position.copy(cameraTarget).addScaledVector(forward,Math.max(.7,hit.distance-.25));}camera.lookAt(cameraTarget);if(active&&effects.shake>.001){camera.position.x+=(Math.random()-.5)*effects.shake;camera.position.y+=(Math.random()-.5)*effects.shake;}
 effects.update(active?realDt:0,camera,player,fighter);if(toastTimer>0){toastTimer-=realDt;if(toastTimer<=0)$('toast').style.opacity=0;}hudTime+=realDt;if(hudTime>.1){hud();hudTime=0;}
 // Move the modest GPU shadow frustum with the player; no full-valley shadow map.
 if(!software){sun.position.set(player.g.position.x-35,60,player.g.position.z+28);sun.target.position.copy(player.g.position);}
 renderer.render(scene,camera);frames++;statsTime+=realDt;if(statsTime>=.75){const elapsed=performance.now()-lastStats;const fps=Math.round(frames*1000/elapsed);text('perf',(software?'Compatibility':'GPU')+' · '+fps+' fps');$('perf').title=renderer.info.render.triangles+' visible triangles';frames=0;statsTime=0;lastStats=performance.now();}
}
hud();requestAnimationFrame(frame);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
